	Method      string            `json:"method,omitempty"`
	Description string            `json:"description,omitempty"`
	Shortcut    string            `json:"shortcut,omitempty"`    // Keyboard shortcut/mnemonic (e.g., "b l")
	Annotations map[string]string `json:"annotations,omitempty"` // Additional metadata (e.g., {"group": "buffers"})
	Intents     []string          `json:"intents,omitempty"`     // Intents satisfied by this method (Phase 10)
}

// Intent structure for goal-oriented routing (Phase 10)
type Intent struct {
	ID        string          `json:"id"`
	Name      string          `json:"name"` // e.g., "intent:save"
	Sender    string          `json:"sender"`
	Payload   json.RawMessage `json:"payload,omitempty"`
	ContextID string          `json:"context_id,omitempty"`
}

// Proposal represents a proactive suggestion from an actor (Phase 12)
type Proposal struct {
	ID          string          `json:"id"`
	Title       string          `json:"title"`       // e.g., "Fix Bug"
	Description string          `json:"description"` // e.g., "I noticed a security flaw, should I run an audit?"
	Action      string          `json:"action"`      // The intent name to trigger if accepted
	Payload     json.RawMessage `json:"payload,omitempty"`
	Metadata    map[string]any  `json:"metadata,omitempty"`
	Confidence  float32         `json:"confidence,omitempty"`
}

// Registration defines a component's presence in the system.
type Registration struct {
	ID           string       `json:"id"`
	Type         string       `json:"type"`
	Status       string       `json:"status,omitempty"`
	Capabilities []Capability `json:"capabilities,omitempty"`
	Background   bool         `json:"background,omitempty"` // Phase 10
	Sidecar      bool         `json:"sidecar,omitempty"`    // Phase 10
	Intents      []string     `json:"intents,omitempty"`    // Phase 10
	Headless     bool         `json:"headless,omitempty"`   // Phase 12
}

// WidgetUpdate represents a content refresh for a specific widget.
type WidgetUpdate struct {
	ID      string `json:"id"`
	Content []byte `json:"content"`
}

// Widget represents a dynamic dashboard tile.
type Widget struct {
	ID                string `json:"id"`
	Title             string `json:"title"`
	ContentType       string `json:"content_type"` // "markdown", "json", "ascii-art"
	Content           []byte `json:"content"`
	RefreshIntervalMs uint32 `json:"refresh_interval_ms"`
}

// MmapRegistry defines the interface for mapping buffers in WASM.
type MmapRegistry interface {
	GetBuffer(id string) (SharedBuffer, bool)
	CreateBuffer(id, name string, initialSize int) (SharedBuffer, error)
}

// SharedBuffer represents a host-side shared memory region.
type SharedBuffer interface {
	GetID() string
	GetName() string
	GetData() []byte
	GetSize() int
	Lock()
	Unlock()
	GetVersion() int
	GetLastModified() int64
	Resize(newSize int) error
	ApplyChange(change BufferChange) error
	OnUpdate(callback func(id string, offset int, length int))
}

// BufferChange represents a mutation to a buffer.
type BufferChange struct {
	Offset    int    `json:"offset"`
	Data      []byte `json:"data"`
	Version   int    `json:"version"`
	Actor     string `json:"actor"`
	Timestamp int64  `json:"timestamp"`
}

// Buffer reflects a handle to shared memory or file-backed storage
type Buffer struct {
	ID           string `json:"id"`
	Name         string `json:"name"`
	Content      []byte `json:"content"`
	Size         int    `json:"size"`
	LastModified int64  `json:"last_modified,omitempty"`
}

// VisualIntent represents a virtual cursor or highlight (Phase 12)
type VisualIntent struct {
	BufferID string `json:"buffer_id"`
	ActorID  string `json:"actor_id"`
	Type     string `json:"type"` // "cursor", "highlight"
	Offset   int    `json:"offset"`
	Length   int    `json:"length,omitempty"`
	Color    string `json:"color,omitempty"`
	Label    string `json:"label,omitempty"`
}

package kernel

import (
	"context"
	"encoding/json"
	"log/slog"
	"os"
	"testing"

	"github.com/james-nesbitt/alloy/api"
)

func TestIntentBroker_ContextInjection(t *testing.T) {
	logger := slog.New(slog.NewTextHandler(os.Stdout, nil))

	// Mock router to capture the message
	var capturedMsg api.Message
	router := func(ctx context.Context, msg api.Message) {
		capturedMsg = msg
	}

	// Mock librarian querier
	querier := func(ctx context.Context, query string) (string, error) {
		if query == "test-query" {
			return "relevant-context-content", nil
		}
		return "", nil
	}

	broker := NewIntentBroker(logger, router, querier)
	broker.Register("test-plugin", []string{"ai:query"})

	// Dispatch an intent that should trigger context injection
	payload, _ := json.Marshal(map[string]string{"prompt": "test-query"})
	intent := api.Intent{
		ID:      "test-intent",
		Name:    "ai:query",
		Sender:  "user",
		Payload: payload,
	}

	err := broker.Dispatch(context.Background(), intent)
	if err != nil {
		t.Fatalf("Dispatch failed: %v", err)
	}

	// Verify the context was injected
	if capturedMsg.Metadata == nil {
		t.Fatal("Metadata is nil, context not injected")
	}

	contextValue, ok := capturedMsg.Metadata["semantic_context"].(string)
	if !ok || contextValue != "relevant-context-content" {
		t.Fatalf("Expected injected context 'relevant-context-content', got '%v'", capturedMsg.Metadata["semantic_context"])
	}
}

func TestIntentBroker_NoInjectionForNonAI(t *testing.T) {
	logger := slog.New(slog.NewTextHandler(os.Stdout, nil))

	// Mock router
	var capturedMsg api.Message
	router := func(ctx context.Context, msg api.Message) {
		capturedMsg = msg
	}

	// Mock librarian querier
	querier := func(ctx context.Context, query string) (string, error) {
		return "should-not-be-injected", nil
	}

	broker := NewIntentBroker(logger, router, querier)
	broker.Register("test-plugin", []string{"other:intent"})

	intent := api.Intent{
		ID:      "test-intent",
		Name:    "other:intent",
		Sender:  "user",
		Payload: []byte(`{"prompt": "test-query"}`),
	}

	err := broker.Dispatch(context.Background(), intent)
	if err != nil {
		t.Fatalf("Dispatch failed: %v", err)
	}

	// Verify no context was injected
	if capturedMsg.Metadata != nil {
		if _, ok := capturedMsg.Metadata["semantic_context"]; ok {
			t.Fatal("Semantic context should not be injected for non-AI intents")
		}
	}
}

