func (i *IdentityManager) matchPerm(perm, action, contextID string) bool {
	// 1. Check for namespace prefix in perm (e.g., "prj-123/buffer:read")
	if strings.Contains(perm, "/") {
		parts := strings.SplitN(perm, "/", 2)
